using System;
using Avalonia;

namespace GnollHackM;

/* Entry point of the Avalonia desktop target; AvaloniaApp is generated by Avalonia.Controls.Maui */
internal static class AvaloniaDesktopProgram
{
    [STAThread]
    public static void Main(string[] args)
        => BuildAvaloniaApp().StartWithClassicDesktopLifetime(args);

    /* X11: GLX with a software fallback, no Vulkan; popups drawn inside the window. 1 GiB GPU resource budget. */
    public static AppBuilder BuildAvaloniaApp()
        => AppBuilder.Configure<AvaloniaApp>()
            .UsePlatformDetect()
            .WithInterFont()
            .LogToTrace()
            .With(new X11PlatformOptions
            {
                RenderingMode = new[] { X11RenderingMode.Glx, X11RenderingMode.Software },
                OverlayPopups = true,
            })
            .With(new SkiaOptions { MaxGpuResourceSizeBytes = 1024L * 1024 * 1024 });
}
